import{z as A,x as d,o as t,c as B,q as s,j as i,D as E,d as e,s as l,S as n,b as r}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"安全启动与签名","description":"","frontmatter":{"title":"安全启动与签名","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/secure-boot.md","filePath":"cs/secure-boot.md","lastUpdated":1791413859000}'),p={name:"cs/secure-boot.md"};function u(c,a,m,h,f,M){const o=d("Mermaid");return t(),B("div",null,[a[2]||(a[2]=s('<h1 id="安全启动与签名" tabindex="-1">安全启动与签名 <a class="header-anchor" href="#安全启动与签名" aria-label="Permalink to &quot;安全启动与签名&quot;">​</a></h1><div class="epigraph"><p>UEFI Secure Boot 用密钥验证引导加载器与内核签名，使未授权映像不能在这条链上启动——除非密钥被你或厂商控制。</p><footer>—— 据 UEFI 规范对 Secure Boot 的说明；Linux 对内核模块签名与 MOK 的文档</footer></div><p><a href="/cs/kernel-audit">audit</a> 记运行时。<a href="/cs/kernel-hardening">加固</a> 假定内核是真的。缺口是 <strong>启动时验证映像</strong>：shim、MOK、与模块签名后课的分工点到启动链。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>恶意 bootloader 可在 LSM 之前赢。Secure Boot：固件用 PK/KEK/db 验签名。Linux：shim 验 grub/内核；用户 MOK 管自签。缺口：禁用 SB 的机器没有这条保证；密钥吊销 dbx。本课不把如何关 SB 当教程。<span class="marginnote">「shim」可以按字面理解成垫片：固件只认 db 里微软/厂商签的章，而 Linux 内核是发行版签的、对不上号——shim 这块小垫片自己带着固件认识的签名先启动，再转手用发行版密钥去验 grub 与内核，把两边对上了。</span></p><p><span class="marginnote">签名的是 PE/EFI 或内核镜像，不是 rootfs 全文——rootfs 要 dm-verity 等另一层。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>上电 → 固件验 boot 应用 → 验内核 → 启动。对照 <a href="/cs/dm-crypt">dm-crypt</a>：加密防读，签名防改启动代码。对照 LSM：时间上签名更早。对照 <a href="/cs/fuse">FUSE</a>：无关。</p>',8)),(t(),i(n,null,{default:E(()=>[l(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20FW%5B%22UEFI%20%E5%AF%86%E9%92%A5%E5%BA%93%22%5D%20--%3E%20SHIM%5B%22%E9%AA%8C%20shim%22%5D%0A%20%20SHIM%20--%3E%20KERN%5B%22%E9%AA%8C%E5%86%85%E6%A0%B8%22%5D%0A%20%20KERN%20--%3E%20INIT%5B%22initramfs%20%E4%BB%8D%E9%9C%80%E5%8F%A6%E9%AA%8C%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[e("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,[e("安全启动把信任锚放到固件密钥，缩小「任意内核」攻击。锚被控则链无意义。不要写成 TPM 全文——下一课度量。与 "),r("a",{href:"/cs/linux-capabilities"},"capabilities"),e("：启动后才有进程。")],-1)),a[5]||(a[5]=r("p",null,"发行版密钥与用户 MOK 的冲突是运维日常。MOK 的验签路径其实是 shim 面前的两次查询：先试厂商 db，再试用户登记的 MOK。",-1)),(t(),i(n,null,{default:E(()=>[l(o,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20IMG%5B%22%E5%BE%85%E5%8A%A0%E8%BD%BD%E7%9A%84%E5%86%85%E6%A0%B8%E6%88%96%E6%A8%A1%E5%9D%97%22%5D%20--%3E%20S%7B%22shim%20%E8%83%BD%E7%94%A8%20db%20%E5%86%85%E5%8E%82%E5%95%86%E5%AF%86%E9%92%A5%E9%AA%8C%E7%AD%BE%3F%22%7D%0A%20%20S%20--%20%22%E6%98%AF%22%20--%3E%20OK%5B%22%E6%94%BE%E8%A1%8C%E5%8A%A0%E8%BD%BD%22%5D%0A%20%20S%20--%20%22%E5%90%A6%22%20--%3E%20M%7B%22MOK%20%E9%87%8C%E7%99%BB%E8%AE%B0%E4%BA%86%E5%8C%B9%E9%85%8D%E7%9A%84%E7%94%A8%E6%88%B7%E8%87%AA%E7%AD%BE%E5%AF%86%E9%92%A5%3F%22%7D%0A%20%20M%20--%20%22%E6%98%AF%22%20--%3E%20OK%0A%20%20M%20--%20%22%E5%90%A6%22%20--%3E%20DEN%5B%22%E6%8B%92%E7%BB%9D%3A%20%E6%9C%AA%E6%8E%88%E6%9D%83%E6%98%A0%E5%83%8F%22%5D%0A%20%20EN%5B%22MokManager%20%E7%99%BB%E8%AE%B0%E6%96%B0%E5%AF%86%E9%92%A5%22%5D%20-.%20%22%E9%9C%80%E6%9C%AC%E6%9C%BA%E7%A1%AE%E8%AE%A4%E5%8F%A3%E4%BB%A4%E5%90%8E%E7%94%9F%E6%95%88%22%20.-%3E%20M%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p>实现上：shim 的 MOK 让用户加自己的密钥，也让恶意者在已解锁机器上加密钥。内核签名过了不等于 initramfs 里的脚本可信，还要单独量。 读法上只引用<a href="/cs/kernel-audit">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>数字感：<span class="marginnote">数字实例：启动链验签覆盖的只是 boot 分区上几 MB 到几十 MB 的镜像；根文件系统动辄数 GB、随时可变——这就是为什么签名只在启动时做一次，而 rootfs 的防篡改要交给 dm-verity 用逐块哈希树在每次读取时校验。</span></p><p>本课在操作系统进阶的「安全、启动与调试 / 内核安全与启动」课序里，对象是 <strong>安全启动与签名</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入每家 OEM 的定制。不保证嵌入式 ROM 引导同构。下一课 TPM 度量启动。</p><p>版本字段会变，课序钉的是机制对象「安全启动与签名」，不是某一主线内核的结构体名。 后课默认：引导映像可被固件验签。PCR 度量链，下一课 TPM。</p><p><span class="marginnote">常见误区：初学者容易以为「打开了 Secure Boot，整机就安全了」——它只保证「未签名代码不在启动链上执行」：物理攻击者换机器、固件本身有洞、rootfs 无验证、MOK 被滥用，哪一条它都不管。它是链条的一节，不是保险箱。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Secure Boot 验引导链签名。</li><li>不自动验证整个根文件系统。</li><li>TPM 度量是下一课。</li><li>出处：UEFI；Linux Secure Boot；shim/MOK。</li></ul>',10))])}const S=A(p,[["render",u]]);export{D as __pageData,S as default};
